package com.asmj.marketplace.discovery;
import java.time.Instant;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="marketplace_extension_requests")
public class MarketplaceExtensionRequest {
 @Id private String id; private String listingId; private String type; private String requesterUserId; private String requesterName; private String requesterEmail; private String message; private String quantity; private String pickupAddress; private String dropAddress; private String status="SUBMITTED"; private String ticketReference; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now();
 public String getId(){return id;} public void setId(String v){id=v;} public String getListingId(){return listingId;} public void setListingId(String v){listingId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getRequesterUserId(){return requesterUserId;} public void setRequesterUserId(String v){requesterUserId=v;} public String getRequesterName(){return requesterName;} public void setRequesterName(String v){requesterName=v;} public String getRequesterEmail(){return requesterEmail;} public void setRequesterEmail(String v){requesterEmail=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getQuantity(){return quantity;} public void setQuantity(String v){quantity=v;} public String getPickupAddress(){return pickupAddress;} public void setPickupAddress(String v){pickupAddress=v;} public String getDropAddress(){return dropAddress;} public void setDropAddress(String v){dropAddress=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getTicketReference(){return ticketReference;} public void setTicketReference(String v){ticketReference=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;}
}
